-- 3.6.0: 사회(성신제T) 뭉탱이 덱(social-bulk) 1255행 추가. 기존 카드는 수정·삭제하지 않는다.
-- 덱 표: social 이름 '기본', social-bulk 추가, 뒤 덱 정렬 한 칸씩.
begin;
do $check$ begin
  if exists (select 1 from public.cards where deck_id='social-bulk') or exists (select 1 from public.decks where id='social-bulk') then raise exception 'social-bulk already exists'; end if;
  if (select count(*) from public.cards) <> 1946 then raise exception 'DB differs from main (expected 1946 cards)'; end if;
end $check$;
update public.decks set subject='사회', name='기본', full_name='사회(성신제T)', teacher='성신제T', description='세계화·국제 갈등·평화·정의관·불평등을 꼬아서.', sort=3 where id='social' and sort=3;
update public.decks set subject='사회', name='조안나T', full_name='사회(조안나T)', teacher='조안나T', description='인권 보장과 헌법: 기본권·기본권 제한·권력 분립·헌법재판소.', sort=5 where id='social-jo' and sort=4;
update public.decks set subject='영어', name='영어', full_name=null, teacher=null, description='고대 건축물·Bartleby·가정법·예술과 측정.', sort=6 where id='english' and sort=5;
update public.decks set subject='생물', name='조용민T', full_name='생물(조용민T)', teacher='조용민T', description='전사·RNA 가공·번역까지. 오페론부터 제외.', sort=7 where id='biology-jo' and sort=6;
update public.decks set subject='생물', name='박상영T', full_name='생물(박상영T)', teacher='박상영T', description='유전 법칙·사람의 유전·돌연변이·유전 물질 + 교사용 핵심 용어 22개.', sort=8 where id='biology-park' and sort=7;
update public.decks set subject='지구과학', name='(황)', full_name='행성우주과학(황)', teacher='황윤환T', description='조립 순서·조작 이유·극축 정렬의 원리.', sort=9 where id='astronomy-hwang' and sort=8;
update public.decks set subject='지구과학', name='(전)', full_name='행성우주과학(전)', teacher='전효진T', description='케플러 법칙·천구 좌표·일주와 연주운동·행성과 달 관측.', sort=10 where id='astronomy-jeon' and sort=9;
update public.decks set subject='물리학Ⅱ', name='물리학Ⅱ', full_name='물리학Ⅱ(6~11단원)', teacher=null, description='수능특강 6~11단원 · 개념 · 새 객관식 · 서술형.', sort=11 where id='physics-ii' and sort=10;
update public.decks set subject='화학', name='화학', full_name='화학(산·염기 평형과 실험)', teacher=null, description='평형 · 산염기 · 중화적정 · 가수분해 · 완충 · 실험 필기 적용.', sort=12 where id='chemistry' and sort=11;
do $verify$ begin
  if (select count(*) from public.cards where deck_id='social-bulk') <> 1255 then raise exception 'count mismatch'; end if;
  if (select count(*) from public.cards) <> 3201 then raise exception 'total mismatch'; end if;
end $verify$;
commit;
